import {roomsFor,TYPES} from './expedition-data.mjs';
// Read-only presentation. All outcomes and unit states come from the recorded event stream.
import {groupActions} from './expedition-report.mjs';
export function replaySteps(events,diagnostic=false){return diagnostic?events.map((e,i)=>({start:i,end:i,roomIndex:e.roomIndex,round:e.round,phase:e.phase,type:e.type,events:[e]})):groupActions(events).filter(g=>!['skip','regen','round'].includes(g.type)||g.events.some(e=>e.detail.reservation||e.detail.healingBlock||e.detail.schedule||e.detail.targetCount?.blocked||e.detail.positionOnly?.blocked||e.detail.attackImmunity||e.detail.mechanismSelection||e.detail.offbeatSelection||e.detail.manaSelection));}
export function adjacentStep(steps,index,delta){const at=steps.findIndex(s=>index>=s.start&&index<=s.end);return at<0?null:steps[at+delta]||null;}
export function sceneFor(config,roomIndex,actualRoom){if(config.expedition==='lockworks')return {theme:'foundry',image:'assets/foundry-v71.png',label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(config.expedition==='ossuary')return {theme:'mirror',image:'assets/mirror-gallery-v9.png',label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(config.expedition==='breakwater')return {theme:'harbor',image:'assets/saltwind-harbor-v41.png',label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(config.expedition==='counterpoint')return {theme:'mirror',image:'assets/mirror-gallery-v9.png',label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(['confluence','greenhouse'].includes(config.expedition))return {theme:'hospice',image:'assets/drowned-infirmary-v21.png',label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(config.expedition==='scriptorium')return {theme:'mirror',image:'assets/mirror-gallery-v9.png',label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(config.expedition==='palisade')return {theme:'harbor',image:'assets/saltwind-harbor-v41.png',label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(config.expedition==='inquest')return {theme:'mirror',image:'assets/mirror-gallery-v9.png',label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(config.expedition==='shoals')return {theme:'harbor',image:'assets/saltwind-harbor-v41.png',label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(config.expedition==='theater')return {theme:'mirror',image:'assets/mirror-gallery-v9.png',label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(config.expedition==='courier')return {theme:'harbor',image:'assets/saltwind-harbor-v41.png',label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(['foundry','foundrywatch'].includes(config.expedition))return {theme:'foundry',image:'assets/foundry-v71.png',label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(config.expedition==='harbor')return {theme:"harbor",image:actualRoom?.node==='seal'||roomIndex===3?"assets/harbor-seal-v41.png":"assets/saltwind-harbor-v41.png",label:actualRoom?.name||roomsFor(config)[roomIndex].name};if(['seasoned','veteran'].includes(config.expedition))return {theme:'trial',image:config.expedition==='seasoned'?'assets/last-lantern-v17.png':'assets/sunken-bell-v10.png',label:roomsFor(config)[roomIndex].name};if(config.expedition==='chapter'&&roomIndex>=3)return {theme:'hospice',image:'assets/drowned-infirmary-v21.png',label:roomsFor(config)[roomIndex].name};if(config.expedition==='hospice')return {theme:'hospice',image:'assets/drowned-infirmary-v21.png',label:['引潮病廊','不息药庭','双灯心室'][roomIndex]};if(config.expedition==='survival')return {theme:'lantern',image:'assets/last-lantern-v17.png',label:['狙灯栈桥','碎灯礼堂','最后一盏灯'][roomIndex]};const mirror=roomIndex===1;return {theme:mirror?'mirror':roomIndex===2?'seal':'iron',image:mirror?'assets/mirror-gallery-v9.png':'assets/abbey.png',label:mirror?'水镜与残响':roomIndex===2?'誓约的尽头':'沉没的门廊'};}
export function stageFrame(group){
 const events=group.events,last=events.at(-1),cast=events.find(e=>e.type==='cast'),lead=cast||events[0],cues=[],links=[];
 for(const e of events){
  if(e.type==='ward-link'||e.type==='ward-release'){const d=e.detail;cues.push({unit:e.targets[0],kind:'control',text:e.type==='ward-link'?'护壁 +'+d.armor:'护壁解除',note:d.sourceName+' · 只影响后续受击',eventId:e.id});if(e.type==='ward-link')links.push({from:e.actor,to:e.targets[0],kind:'support',eventId:e.id});}
  if(e.type==='reinforcement')for(const u of e.detail.wave.arrivals)cues.push({unit:u.id,kind:'summon',text:'增援抵达',note:'第'+e.detail.wave.index+'/'+e.detail.wave.total+'波',eventId:e.id});
  if(e.type==='initiative-check')cues.push({unit:e.actor,kind:'mana',text:e.detail.cost?'先攻 −'+e.detail.cost+' MP':'自然先攻',note:e.detail.initiative.reason||'独立先攻选择 · 不占行动',eventId:e.id});
  if(e.type==='health-phase')cues.push({unit:e.actor,kind:'control',text:e.detail.healthPhase.name,note:'生命阶段变化 · 既定队列保留',eventId:e.id});
  if(e.type==='withdraw')for(const u of e.detail.withdrawal.alive)cues.push({unit:u.id,kind:'control',text:'整队撤退',note:'仍存活，不算本房通关',eventId:e.id});
  if(e.type==='initiative'&&e.detail.actionLimits)for(const l of e.detail.actionLimits)cues.push({unit:l.target,kind:'control',text:l.removed?'额外行动 −'+l.removed:'迟拍未减',note:l.before+'→'+l.after+'次普通行动',eventId:e.id});
  if(e.type==='immune')cues.push({unit:e.targets[0],kind:'control',text:'免疫',note:'本次0伤害',eventId:e.id});
  else if(e.type==='attack'||e.type==='harm'){const d=e.detail,kind=d.grade==='闪避'?'miss':d.actual>0?'damage':'blocked';cues.push({unit:e.targets[0],kind,text:kind==='miss'?'闪避':kind==='blocked'?'吸收':`−${d.actual}`,note:(e.type==='harm'?'潮蚀持续伤害':d.mechanismHit?'机关耐久拆解 · '+d.grade:d.grade)+(d.damageChannel?' · '+TYPES[d.attackType]+'攻防/'+TYPES[d.damageType]+'伤害':'')+(d.resistance>0?' · 抗性减伤':d.resistance<0?' · 弱点':''),eventId:e.id});}
  else if(e.type==='intercept'||e.type==='intercept-skip')cues.push({unit:e.actor,kind:'cover',text:e.type==='intercept'?(e.detail.success?'接招':'援护未及'):'援护未触发',note:e.detail.reason||'2法力 · 不占普通行动',eventId:e.id});
  else if(e.type==='mana-damage')cues.push({unit:e.targets[0],kind:'mana',text:e.detail.grade==='闪避'?'闪避':'−'+e.detail.actual+' MP',note:'断流 · 生命不变',eventId:e.id});
  else if(e.type==='mana-transfer')cues.push({unit:e.targets[0],kind:'mana',text:'+'+e.detail.actual+' MP',note:'借潮咏 · 来源付'+e.detail.paidMana+'法力/普通行动',eventId:e.id});
  else if(e.type==='heal')cues.push({unit:e.targets[0],kind:'heal',text:'+'+e.detail.actual,note:e.detail.passive?'缓释':'救护',eventId:e.id});
  else if(e.type==='item')cues.push({unit:e.actor,kind:e.detail.resource==='hp'?'heal':'mana',text:'+'+e.detail.actual,note:e.detail.resource==='hp'?'药匣恢复':'药瓶回蓝',eventId:e.id});
  else if(['effect','dispel','cleanse','activate','summon','down','dismiss','defend'].includes(e.type)){
   const unit=e.type==='defend'?e.actor:e.targets[0],kind=e.type==='dispel'?'control':e.type==='effect'?(e.detail.harmful?'control':e.detail.active===false?'pending':'buff'):e.type;
   cues.push({unit,kind,text:e.type==='dispel'?'破印':e.type==='cleanse'?'净化':e.type==='defend'?e.detail.name:e.type==='summon'?'召唤':e.type==='down'?(e.detail.mechanism?'已拆除':'倒下'):e.type==='dismiss'?(e.detail.recall?'召回':'消散'):e.type==='activate'?'生效':e.detail.stat==='extraActionLimit'&&e.detail.active===false?'迟拍待生效':e.detail.harmful?(e.detail.component||'负面'):e.detail.active===false?'待生效':'增益',note:e.detail.component||'',eventId:e.id});
  }
  if(e.detail.healingBlock||e.detail.healingDecision?.status==='blocked')cues.push({unit:e.actor,kind:'control',text:'救护受阻',note:'按普通指令继续',eventId:e.id});
  if(e.type==='intercept'&&e.detail.success)links.push({from:e.actor,to:e.targets[0],kind:'support',eventId:e.id});
  if(['attack','mana-damage','harm','dispel','mana-transfer','heal','effect','cleanse','summon','activate','expire'].includes(e.type))for(const target of e.targets)links.push({from:e.actor,to:target,kind:['mana-damage','dispel','harm'].includes(e.type)?'control':e.type==='attack'?e.detail.attackType:e.type==='effect'?(e.detail.harmful?'control':e.detail.active===false?'pending':'support'):e.type,eventId:e.id});
 }
 return {units:structuredClone(last.units),actor:lead.actor,targets:[...new Set(cues.map(c=>c.unit).filter(Boolean))],cues,links,phase:lead.phase,round:lead.round,supplies:structuredClone(last.supplies),transition:['health-phase','wave-clear','reinforcement','withdraw','room','victory','defeat','scene','encounter','route','rescue','branch'].includes(lead.type)?lead.type:null};
}
